// Fails when the committed contract artifacts no longer match contracts/*.sol.
//
// contracts/out/*.json and src/lib/abis/*.ts are generated by scripts/compile.ts
// and committed, so the frontend can deploy and call the contracts without a
// compile step. Nothing used to check that they were regenerated after a
// source change, so an ABI could silently describe a contract that no longer
// exists. Bytecode is compared without solc's metadata suffix (see
// stripMetadata): only a behavioural difference fails the check.
//
// Run: bun run contracts:check
import * as fs from "node:fs";
import * as path from "node:path";
import {
  CONTRACTS,
  ROOT,
  camelName,
  compileContracts,
  stripMetadata,
} from "./lib/compile-contracts";

const compiled = compileContracts();
const problems: string[] = [];

for (const name of CONTRACTS) {
  const fresh = compiled.contracts[name];
  const outFile = path.join(ROOT, "contracts", "out", `${name}.json`);
  const out = JSON.parse(fs.readFileSync(outFile, "utf8")) as { abi: unknown; bytecode: string };
  if (JSON.stringify(out.abi) !== JSON.stringify(fresh.abi)) {
    problems.push(`contracts/out/${name}.json: ABI differs from the source`);
  }
  if (stripMetadata(out.bytecode) !== stripMetadata(fresh.bytecode)) {
    problems.push(`contracts/out/${name}.json: bytecode differs from the source`);
  }

  const camel = camelName(name);
  const ts = fs.readFileSync(path.join(ROOT, "src", "lib", "abis", `${camel}.ts`), "utf8");
  const abiMatch = ts.match(new RegExp(`export const ${camel}Abi = (.*) as const;`));
  const binMatch = ts.match(new RegExp(`export const ${camel}Bytecode = "(0x[0-9a-f]*)"`));
  if (!abiMatch || JSON.stringify(JSON.parse(abiMatch[1])) !== JSON.stringify(fresh.abi)) {
    problems.push(`src/lib/abis/${camel}.ts: ABI differs from the source`);
  }
  if (!binMatch || stripMetadata(binMatch[1]) !== stripMetadata(fresh.bytecode)) {
    problems.push(`src/lib/abis/${camel}.ts: bytecode differs from the source`);
  }
}

if (problems.length > 0) {
  for (const p of problems) console.error(`✗ ${p}`);
  console.error("\nRun `bun run contracts:compile` and commit the result.");
  process.exit(1);
}
console.log(
  `✓ ${CONTRACTS.length} contracts match their committed artifacts (solc ${compiled.version}).`,
);
